/* PROSRC LINES COUNT */
--ReqID:SRS-SQL-PACKAGE
--use dynamic sql to support package
CREATE OR REPLACE FUNCTION SYS._ORA_SRC_COUNT(objectid OID,table_name TEXT,
src_name text)
RETURNS INTEGER AS $$
DECLARE
	RET INTEGER;
	stmt_query text;
BEGIN
   /* Begin - BUG#Z370 */
   IF (table_name = 'PG_PROC') THEN
      stmt_query := 'SELECT COUNT(1) from (SELECT UNNEST(STRING_TO_ARRAY(pg_get_functiondef(' || objectid || ')'|| ',CHR(10)))) AS SQ';
   ELSE
   /* End - BUG#Z370 */
     stmt_query := 'SELECT COUNT(1) FROM (SELECT UNNEST(STRING_TO_ARRAY(' || src_name || ',CHR(10)))' ||
       ' FROM ' || table_name || ' WHERE oid = ' || objectid || ') AS SQ';
   /* Begin - BUG#Z370 */
   END IF;
   /* End - BUG#Z370 */

   EXECUTE stmt_query INTO RET;
   RETURN RET;
END;
$$ LANGUAGE PLPGSQL IMMUTABLE;

/* DBA_SOURCE */
/* Begin - ReqID:SRS-SQL-PACKAGE */
--use proc_source
CREATE OR REPLACE VIEW SYS.DBA_PROC_SOURCE AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PROOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	CASE
		WHEN P.PROKIND = 'f'
			THEN 'FUNCTION'
		ELSE 'PROCEDURE'
	END::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID, 'PG_PROC', 'PROSRC'))::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY(substring(pg_get_functiondef(P.OID), length('CREATE OR REPLACE ') + 1), CHR(10)))::VARCHAR2(4000) AS TEXT,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN PG_TRIGGER AS T
		ON P.OID = T.TGFOID
WHERE
	P.PROKIND = ANY(ARRAY['p', 'f'])
	AND T.OID IS NULL
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
;

GRANT SELECT ON SYS.DBA_PROC_SOURCE TO PUBLIC;

--interle include extral some cols which will be
--used in others view about package
CREATE OR REPLACE VIEW SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL AS
SELECT
    P.PKGOWNER AS OWNER_ID,
	P.OID,
	P.PKGNAMESPACE AS NAMESPACE_ID,
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PKGOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PKGNAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	'PACKAGE'::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID,'PG_PACKAGE', 'PKGSRC') + 1)::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY('PACKAGE '  || SYS.ORA_CASE_TRANS(P.PKGNAME::VARCHAR2) ||' IS' || CHR(10) || P.PKGSRC
	  /* Begin - BUG#Z369 */
	  || ';'
	  /* End - BUG#Z369 */
	  , CHR(10)))::VARCHAR2(4000) AS TEXT,
	  0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PACKAGE AS P
WHERE
	P.PKGNAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PKGNAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PKGNAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
;

--grant it to public
GRANT SELECT ON SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL AS
SELECT
    P1.PKGOWNER AS OWNER_ID,
	P1.OID,
	P1.PKGNAMESPACE AS NAMESPACE_ID,
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P1.PKGOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P1.PKGNAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	'PACKAGE BODY'::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID,'PG_PACKAGE_BODY', 'BODYSRC') + 1)::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY('PACKAGE BODY '  || SYS.ORA_CASE_TRANS(P1.PKGNAME::VARCHAR2) ||' IS' || CHR(10) || P.BODYSRC
	  /* Begin - BUG#Z369 */
	  || ';'
	  /* End - BUG#Z369 */
	  , CHR(10)))::VARCHAR2(4000) AS TEXT,
	  0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PACKAGE_BODY AS P LEFT JOIN PG_PACKAGE AS P1
	ON P.PKGOID = P1.OID
WHERE
	P1.PKGNAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P1.PKGNAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P1.PKGNAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
;

GRANT SELECT ON SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_PACKAGE_SOURCE AS
	(SELECT OWNER,NAME,TYPE,LINE,TEXT,ORIGIN_CON_ID FROM
   SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL) --come from pg_package
UNION ALL
	(SELECT OWNER,NAME,TYPE,LINE,TEXT,ORIGIN_CON_ID FROM
	SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL); --come from pg_package_body

GRANT SELECT ON SYS.DBA_PACKAGE_SOURCE TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_SOURCE AS
	SELECT * FROM SYS.DBA_PROC_SOURCE --come from functions or procedures
UNION ALL
	SELECT * FROM SYS.DBA_PACKAGE_SOURCE;	--come from packages
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.DBA_SOURCE TO PUBLIC;

/* ALL_SOURCE */
CREATE OR REPLACE VIEW SYS.ALL_PROC_SOURCE AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PROOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	CASE
		WHEN P.PROKIND = 'f'
			THEN 'FUNCTION'
		ELSE 'PROCEDURE'
	END::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID, 'PG_PROC', 'PROSRC'))::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY(substring(pg_get_functiondef(P.OID), length('CREATE OR REPLACE ') + 1), CHR(10)))::VARCHAR2(4000) AS TEXT,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN PG_TRIGGER AS T
		ON P.OID = T.TGFOID
WHERE
	P.PROKIND = ANY(ARRAY['p', 'f'])
	AND T.OID IS NULL
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND HAS_SCHEMA_PRIVILEGE(P.PRONAMESPACE, 'USAGE')	/* BUG#Z169 */
	AND HAS_FUNCTION_PRIVILEGE(P.OID, 'EXECUTE')
;

GRANT SELECT ON SYS.ALL_PROC_SOURCE TO PUBLIC;
/* Begin - ReqID:SRS-SQL-PACKAGE */
CREATE OR REPLACE VIEW SYS.ALL_PACKAGE_SOURCE AS
	(SELECT OWNER, NAME,TYPE,
   LINE,TEXT,ORIGIN_CON_ID FROM SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL P
   WHERE HAS_SCHEMA_PRIVILEGE(P.NAMESPACE_ID, 'USAGE') AND
	HAS_PACKAGE_PRIVILEGE(P.OID, 'EXECUTE')) --come from pg_package
UNION ALL
	(SELECT OWNER,NAME,TYPE,LINE,
	TEXT,ORIGIN_CON_ID FROM SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL P
	WHERE HAS_SCHEMA_PRIVILEGE(P.NAMESPACE_ID, 'USAGE') AND
	HAS_PACKAGE_PRIVILEGE(P.OID, 'EXECUTE')); --come from pg_package_body

GRANT SELECT ON SYS.ALL_PACKAGE_SOURCE TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_SOURCE AS
	SELECT * FROM SYS.ALL_PROC_SOURCE --come from procedures or functions
UNION ALL
	SELECT * FROM SYS.ALL_PACKAGE_SOURCE; --come from packages
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.ALL_SOURCE TO PUBLIC;

/* USER_SOURCE */
CREATE OR REPLACE VIEW SYS.USER_PROC_SOURCE AS
SELECT
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS NAME,
	CASE
		WHEN P.PROKIND = 'f'
			THEN 'FUNCTION'
		ELSE 'PROCEDURE'
	END::VARCHAR2(12) AS TYPE,
	GENERATE_SERIES(1::INTEGER, SYS._ORA_SRC_COUNT(P.OID, 'PG_PROC', 'PROSRC'))::NUMBER AS LINE,
	UNNEST(STRING_TO_ARRAY(substring(pg_get_functiondef(P.OID), length('CREATE OR REPLACE ') + 1), CHR(10)))::VARCHAR2(4000) AS TEXT,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN PG_TRIGGER AS T
		ON P.OID = T.TGFOID
WHERE
	P.PROKIND = ANY(ARRAY['p', 'f'])
	AND T.OID IS NULL
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND PG_GET_USERBYID(P.PROOWNER) = CURRENT_USER	/* BUG#M0000074 */
;

GRANT SELECT ON SYS.USER_PROC_SOURCE TO PUBLIC;

/* Begin - ReqID:SRS-SQL-PACKAGE */
CREATE OR REPLACE VIEW SYS.USER_PACKAGE_SOURCE AS
	(SELECT NAME,TYPE,
   LINE,TEXT,ORIGIN_CON_ID FROM SYS.DBA_PACKAGE_SPEC_SOURCE_INTERNEL P
   WHERE PG_GET_USERBYID(P.OWNER_ID) = CURRENT_USER) /* BUG#M0000074 */ --come from pg_package
UNION ALL
	(SELECT NAME,TYPE,LINE,
	TEXT,ORIGIN_CON_ID FROM SYS.DBA_PACKAGE_BODY_SOURCE_INTERNEL P
	WHERE PG_GET_USERBYID(P.OWNER_ID) = CURRENT_USER); /* BUG#M0000074 */ --come from pg_package_body

GRANT SELECT ON SYS.USER_PACKAGE_SOURCE TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_SOURCE AS
  SELECT * FROM SYS.USER_PROC_SOURCE --come from functions or procedures
UNION ALL
  SELECT * FROM SYS.USER_PACKAGE_SOURCE; --come from packages
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.USER_SOURCE TO PUBLIC;

/* ARGUMENTS' TYPE COUNT */
CREATE OR REPLACE FUNCTION SYS._ORA_ARGS_COUNT(PROID OID)
RETURNS INTEGER
AS $$
DECLARE
	RET INTEGER;
BEGIN
	SELECT
		COUNT(1)
	FROM
	(
		SELECT
			UNNEST(
				CASE
					WHEN PROALLARGTYPES IS NOT NULL
						THEN PROALLARGTYPES
					ELSE PROARGTYPES
				END
			)
		FROM
			PG_PROC
		WHERE OID = $1
	) AS SQ
	INTO
		RET;
	RETURN RET;
END;
$$ LANGUAGE PLPGSQL IMMUTABLE;

/* DBA_ARGUMENTS */
CREATE OR REPLACE VIEW SYS.DBA_PROC_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PROOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	NULL::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	1::NUMBER AS SUBPROGRAM_ID,
	SYS.ORA_CASE_TRANS(
		SQ.ARGUMENT_NAME::VARCHAR2
	)::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.PROKIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN 'FLOAT'
		WHEN T.TYPNAME = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN T.TYPNAME = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	/* Begin - BUG#Z170 */
	CASE
		WHEN PG_GET_FUNCTION_ARG_DEFAULT(SQ.OID, SQ.POSITION) IS NULL
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	/* End - BUG#Z170 */
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_LENGTH IS NOT NULL
		    THEN ARG.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'float4', 'float8',
								   'numeric', 'number'])
			THEN 22
		WHEN T.TYPNAME = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_PRECISION IS NOT NULL
		    THEN ARG.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8'])
			THEN 38
		WHEN T.TYPNAME = 'float4'
			THEN 63
		WHEN T.TYPNAME = 'float8'
			THEN 126
		WHEN T.TYPNAME = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_SCALE IS NOT NULL
		    THEN ARG.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN T.TYPNAME = ANY(ARRAY['numeric', 'number',
								   'int2', 'int4', 'int8',
								   'float4', 'float8'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_NAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_NAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	CASE
	   WHEN ARG.TYPE_SUBNAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_SUBNAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_SUBNAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_OBJECT_TYPE != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_OBJECT_TYPE::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
    /* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN (T.TYPTYPE = 'b' OR T.TYPTYPE = 'c') AND ARG.PLS_TYPE IS NOT NULL
			THEN SYS.ORA_CASE_TRANS(ARG.PLS_TYPE)
		WHEN T.TYPTYPE = 'b' AND ARG.PLS_TYPE IS NULL
			THEN SYS.ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'raw'
			THEN 'RAW'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'blob'
			THEN 'BLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'clob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'nclob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long'
			THEN 'LONG'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long_raw'
			THEN 'LONG_RAW'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN
	(
		SELECT
			OID,
			NULL AS ARGUMENT_NAME,
			PRORETTYPE AS DATA_TYPE,
			'o' AS IN_OUT,
			0 AS POSITION
		FROM
			PG_PROC
		WHERE
			PROKIND = 'f'
		UNION ALL
		SELECT
			OID,
			UNNEST(PROARGNAMES) AS ARGUMENT_NAME,
			UNNEST(
			CASE
				WHEN PROALLARGTYPES IS NOT NULL
					THEN PROALLARGTYPES
				ELSE PROARGTYPES
			END) AS DATA_TYPE,
			UNNEST(PROARGMODES) AS IN_OUT,
			GENERATE_SERIES(1, SYS._ORA_ARGS_COUNT(OID)) AS POSITION
		FROM
			PG_PROC
	) AS SQ
		ON P.OID = SQ.OID
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN 
	(
		SELECT
			OID,
			POSITION,
			TYPE_NAME,
			TYPE_SUBNAME,
			TYPE_OBJECT_TYPE,
			DATA_LENGTH,
			DATA_PRECISION,
			DATA_SCALE,
			PLS_TYPE
		FROM
	       pg_get_function_arg_reference_typerowtype()
	) AS ARG ON ARG.OID = SQ.OID AND ARG.POSITION = SQ.POSITION
	/* End - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN PG_TYPE AS T
		ON SQ.DATA_TYPE = T.OID
	LEFT JOIN PG_TRIGGER AS TR
		ON P.OID = TR.TGFOID
WHERE
	TR.OID IS NULL 
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;

/* Begin - ReqID:SRS-SQL-PACKAGE */
GRANT SELECT ON SYS.DBA_PROC_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_PACKAGE_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.OWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PROC_NAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	SYS.ORA_CASE_TRANS(P.PACKAGE_NAME::VARCHAR2)::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	(P.FNO + 1)::NUMBER AS SUBPROGRAM_ID,
	CASE
	   WHEN SQ.ARGUMENT_NAME != '_NULL_' AND SQ.ARGUMENT_NAME != '_null_'
	        THEN SYS.ORA_CASE_TRANS(SQ.ARGUMENT_NAME::VARCHAR2)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.KIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN 'FLOAT'
		WHEN SQ.DATA_TYPE = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN SQ.DATA_TYPE = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(SQ.DATA_TYPE)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	CASE
		WHEN SQ.ARGDEFAULT = '_NULL_'
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_LENGTH != 0
		    THEN SQ.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'real', 'double precision',
								   'numeric', 'number'])
			THEN 22
		WHEN SQ.DATA_TYPE = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_PRECISION != 0
		    THEN SQ.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint'])
			THEN 38
		WHEN SQ.DATA_TYPE = 'real'
			THEN 63
		WHEN SQ.DATA_TYPE = 'double precision'
			THEN 126
		WHEN SQ.DATA_TYPE = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_SCALE != 0
		    THEN SQ.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN SQ.DATA_TYPE= ANY(ARRAY['numeric', 'number',
								   'smallint', 'integer', 'bigint',
								   'real', 'double precision'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_NAME IS NOT NULL AND SQ.TYPE_NAME != '_NULL_' AND SQ.TYPE_NAME != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_NAME)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_SUBNAME,
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE IS NOT NULL AND SQ.TYPE_OBJECT_TYPE != '_NULL_' AND SQ.TYPE_OBJECT_TYPE != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_OBJECT_TYPE)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE = 'table' OR SQ.TYPE_OBJECT_TYPE = 'TABLE' OR SQ.TYPE_OBJECT_TYPE = 'view' OR SQ.TYPE_OBJECT_TYPE = 'VIEW'
			THEN 'ROWTYPE'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	/* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_GET_SUBPROCS_IN_PACKAGE() AS P
	LEFT JOIN
	(
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(0, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE KIND = 'f'
		UNION ALL
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(1, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE NARGS > 0 AND KIND = 'p'
	) AS SQ
		ON P.OID = SQ.OID AND P.FNO = SQ.FNO
WHERE
    SQ.POSITION IS NOT NULL
	AND P.NAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;

GRANT SELECT ON SYS.DBA_PACKAGE_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.DBA_ARGUMENTS AS
	SELECT * FROM SYS.DBA_PROC_ARGUMENTS --come from pg_proc
UNION ALL
	SELECT * FROM SYS.DBA_PACKAGE_ARGUMENTS --come from pg_package
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.DBA_ARGUMENTS TO PUBLIC;

/* ALL_ARGUMENTS */
CREATE OR REPLACE VIEW SYS.ALL_PROC_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.PROOWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	NULL::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	1::NUMBER AS SUBPROGRAM_ID,
	SYS.ORA_CASE_TRANS(
		SQ.ARGUMENT_NAME::VARCHAR2
	)::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.PROKIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN 'FLOAT'
		WHEN T.TYPNAME = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN T.TYPNAME = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	/* Begin - BUG#Z170 */
	CASE
		WHEN PG_GET_FUNCTION_ARG_DEFAULT(SQ.OID, SQ.POSITION) IS NULL
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	/* End - BUG#Z170 */
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_LENGTH IS NOT NULL
		    THEN ARG.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'float4', 'float8',
								   'numeric', 'number'])
			THEN 22
		WHEN T.TYPNAME = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_PRECISION IS NOT NULL
		    THEN ARG.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8'])
			THEN 38
		WHEN T.TYPNAME = 'float4'
			THEN 63
		WHEN T.TYPNAME = 'float8'
			THEN 126
		WHEN T.TYPNAME = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_SCALE IS NOT NULL
		    THEN ARG.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN T.TYPNAME = ANY(ARRAY['numeric', 'number',
								   'int2', 'int4', 'int8',
								   'float4', 'float8'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_NAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_NAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	CASE
	   WHEN ARG.TYPE_SUBNAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_SUBNAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_SUBNAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_OBJECT_TYPE != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_OBJECT_TYPE::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
    /* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN (T.TYPTYPE = 'b' OR T.TYPTYPE = 'c') AND ARG.PLS_TYPE IS NOT NULL
			THEN SYS.ORA_CASE_TRANS(ARG.PLS_TYPE)
		WHEN T.TYPTYPE = 'b' AND ARG.PLS_TYPE IS NULL
			THEN SYS.ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'raw'
			THEN 'RAW'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'blob'
			THEN 'BLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'clob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'nclob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long'
			THEN 'LONG'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long_raw'
			THEN 'LONG_RAW'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN
	(
		SELECT
			OID,
			NULL AS ARGUMENT_NAME,
			PRORETTYPE AS DATA_TYPE,
			'o' AS IN_OUT,
			0 AS POSITION
		FROM
			PG_PROC
		WHERE
			PROKIND = 'f'
		UNION ALL
		SELECT
			OID,
			UNNEST(PROARGNAMES) AS ARGUMENT_NAME,
			UNNEST(
			CASE
				WHEN PROALLARGTYPES IS NOT NULL
					THEN PROALLARGTYPES
				ELSE PROARGTYPES
			END) AS DATA_TYPE,
			UNNEST(PROARGMODES) AS IN_OUT,
			GENERATE_SERIES(1, SYS._ORA_ARGS_COUNT(OID)) AS POSITION
		FROM
			PG_PROC
	) AS SQ
		ON P.OID = SQ.OID
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN
	(
		SELECT
			OID,
			POSITION,
			TYPE_NAME,
			TYPE_SUBNAME,
			TYPE_OBJECT_TYPE,
			DATA_LENGTH,
			DATA_PRECISION,
			DATA_SCALE,
			PLS_TYPE
		FROM
	       pg_get_function_arg_reference_typerowtype()
	) AS ARG ON ARG.OID = SQ.OID AND ARG.POSITION = SQ.POSITION
	/* End - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN PG_TYPE AS T
		ON SQ.DATA_TYPE = T.OID
	LEFT JOIN PG_TRIGGER AS TR
		ON P.OID = TR.TGFOID
WHERE
	TR.OID IS NULL 
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND HAS_SCHEMA_PRIVILEGE(P.PRONAMESPACE, 'USAGE')	/* BUG#Z169 */
	AND HAS_FUNCTION_PRIVILEGE(P.OID, 'EXECUTE')
ORDER BY
	OWNER, OBJECT_ID
;

/* Begin - ReqID:SRS-SQL-PACKAGE */
GRANT SELECT ON SYS.ALL_PROC_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_PACKAGE_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(
		PG_GET_USERBYID(P.OWNER)::VARCHAR2
	)::VARCHAR2(128) AS OWNER,
	SYS.ORA_CASE_TRANS(P.PROC_NAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	SYS.ORA_CASE_TRANS(P.PACKAGE_NAME::VARCHAR2)::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	(P.FNO + 1)::NUMBER AS SUBPROGRAM_ID,
	CASE
	   WHEN SQ.ARGUMENT_NAME != '_NULL_' AND SQ.ARGUMENT_NAME != '_null_'
	        THEN SYS.ORA_CASE_TRANS(SQ.ARGUMENT_NAME::VARCHAR2)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.KIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN 'FLOAT'
		WHEN SQ.DATA_TYPE = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN SQ.DATA_TYPE = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(SQ.DATA_TYPE)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	CASE
		WHEN SQ.ARGDEFAULT = '_NULL_'
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_LENGTH != 0
		    THEN SQ.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'real', 'double precision',
								   'numeric', 'number'])
			THEN 22
		WHEN SQ.DATA_TYPE = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_PRECISION != 0
		    THEN SQ.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint'])
			THEN 38
		WHEN SQ.DATA_TYPE = 'real'
			THEN 63
		WHEN SQ.DATA_TYPE = 'double precision'
			THEN 126
		WHEN SQ.DATA_TYPE = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_SCALE != 0
		    THEN SQ.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN SQ.DATA_TYPE= ANY(ARRAY['numeric', 'number',
								   'smallint', 'integer', 'bigint',
								   'real', 'double precision'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_NAME IS NOT NULL AND SQ.TYPE_NAME != '_NULL_' AND SQ.TYPE_NAME != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_NAME)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_SUBNAME,
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE IS NOT NULL AND SQ.TYPE_OBJECT_TYPE != '_NULL_' AND SQ.TYPE_OBJECT_TYPE != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_OBJECT_TYPE)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE = 'table' OR SQ.TYPE_OBJECT_TYPE = 'TABLE' OR SQ.TYPE_OBJECT_TYPE = 'view' OR SQ.TYPE_OBJECT_TYPE = 'VIEW'
			THEN 'ROWTYPE'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	/* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_GET_SUBPROCS_IN_PACKAGE() AS P
	LEFT JOIN
	(
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(0, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE KIND = 'f'
		UNION ALL
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(1, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE NARGS > 0 AND KIND = 'p'
	) AS SQ
		ON P.OID = SQ.OID AND P.FNO = SQ.FNO
WHERE
    SQ.POSITION IS NOT NULL
	AND P.NAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND HAS_SCHEMA_PRIVILEGE(P.NAMESPACE, 'USAGE')	/* BUG#Z169 */
	AND HAS_PACKAGE_PRIVILEGE(P.OID, 'EXECUTE')
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;

GRANT SELECT ON SYS.ALL_PACKAGE_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_ARGUMENTS AS
	SELECT * FROM SYS.ALL_PROC_ARGUMENTS --come from pg_proc
UNION ALL
	SELECT * FROM SYS.ALL_PACKAGE_ARGUMENTS --come from pg_package
ORDER BY
	OWNER, OBJECT_ID,OBJECT_NAME
;
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.ALL_ARGUMENTS TO PUBLIC;

/* USER_ARGUMENTS */
CREATE OR REPLACE VIEW SYS.USER_PROC_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(P.PRONAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	NULL::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	1::NUMBER AS SUBPROGRAM_ID,
	SYS.ORA_CASE_TRANS(
		SQ.ARGUMENT_NAME::VARCHAR2
	)::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.PROKIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR ARG.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN 'FLOAT'
		WHEN T.TYPNAME = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN T.TYPNAME = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	/* Begin - BUG#Z170 */
	CASE
		WHEN PG_GET_FUNCTION_ARG_DEFAULT(SQ.OID, SQ.POSITION) IS NULL
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	/* End - BUG#Z170 */
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_LENGTH IS NOT NULL
		    THEN ARG.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8',
								   'float4', 'float8',
								   'numeric', 'number'])
			THEN 22
		WHEN T.TYPNAME = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_PRECISION IS NOT NULL
		    THEN ARG.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['int2', 'int4', 'int8'])
			THEN 38
		WHEN T.TYPNAME = 'float4'
			THEN 63
		WHEN T.TYPNAME = 'float8'
			THEN 126
		WHEN T.TYPNAME = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN ARG.DATA_SCALE IS NOT NULL
		    THEN ARG.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN T.TYPNAME = ANY(ARRAY['float4', 'float8'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN T.TYPNAME = ANY(ARRAY['numeric', 'number',
								   'int2', 'int4', 'int8',
								   'float4', 'float8'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_NAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_NAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	CASE
	   WHEN ARG.TYPE_SUBNAME != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_SUBNAME::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_SUBNAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
	   WHEN ARG.TYPE_OBJECT_TYPE != '_NULL_'
	        THEN SYS.ORA_CASE_TRANS(ARG.TYPE_OBJECT_TYPE::VARCHAR2)::VARCHAR2(128)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
    /* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN (T.TYPTYPE = 'b' OR T.TYPTYPE = 'c') AND ARG.PLS_TYPE IS NOT NULL
			THEN SYS.ORA_CASE_TRANS(ARG.PLS_TYPE)
		WHEN T.TYPTYPE = 'b' AND ARG.PLS_TYPE IS NULL
			THEN SYS.ORA_CASE_TRANS(T.OID::REGTYPE::VARCHAR2)
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'raw'
			THEN 'RAW'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'blob'
			THEN 'BLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'clob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'nclob'
			THEN 'CLOB'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long'
			THEN 'LONG'
		WHEN T.TYPTYPE = 'd' AND T.TYPNAME = 'long_raw'
			THEN 'LONG_RAW'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN T.OID::REGTYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_PROC AS P
	LEFT JOIN
	(
		SELECT
			OID,
			NULL AS ARGUMENT_NAME,
			PRORETTYPE AS DATA_TYPE,
			'o' AS IN_OUT,
			0 AS POSITION
		FROM
			PG_PROC
		WHERE
			PROKIND = 'f'
		UNION ALL
		SELECT
			OID,
			UNNEST(PROARGNAMES) AS ARGUMENT_NAME,
			UNNEST(
			CASE
				WHEN PROALLARGTYPES IS NOT NULL
					THEN PROALLARGTYPES
				ELSE PROARGTYPES
			END) AS DATA_TYPE,
			UNNEST(PROARGMODES) AS IN_OUT,
			GENERATE_SERIES(1, SYS._ORA_ARGS_COUNT(OID)) AS POSITION
		FROM
			PG_PROC
	) AS SQ
		ON P.OID = SQ.OID
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN
	(
		SELECT
			OID,
			POSITION,
			TYPE_NAME,
			TYPE_SUBNAME,
			TYPE_OBJECT_TYPE,
			DATA_LENGTH,
			DATA_PRECISION,
			DATA_SCALE,
			PLS_TYPE
		FROM
	       pg_get_function_arg_reference_typerowtype()
	) AS ARG ON ARG.OID = SQ.OID AND ARG.POSITION = SQ.POSITION
	/* End - ReqID:SRS-PLSQL-TYPE */
	LEFT JOIN PG_TYPE AS T
		ON SQ.DATA_TYPE = T.OID
	LEFT JOIN PG_TRIGGER AS TR
		ON P.OID = TR.TGFOID
WHERE
	TR.OID IS NULL 
	AND P.PRONAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.PRONAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND PG_GET_USERBYID(P.PROOWNER) = CURRENT_USER	/* BUG#M0000074 */
ORDER BY
	OBJECT_ID
;

/* Begin - ReqID:SRS-SQL-PACKAGE */
GRANT SELECT ON SYS.USER_PROC_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_PACKAGE_ARGUMENTS AS
SELECT
	SYS.ORA_CASE_TRANS(P.PROC_NAME::VARCHAR2)::VARCHAR2(128) AS OBJECT_NAME,
	SYS.ORA_CASE_TRANS(P.PACKAGE_NAME::VARCHAR2)::VARCHAR2(128) AS PACKAGE_NAME,
	P.OID::VARCHAR2(10)::NUMBER AS OBJECT_ID,
	NULL::VARCHAR2(40) AS OVERLOAD,
	(P.FNO + 1)::NUMBER AS SUBPROGRAM_ID,
	CASE
	   WHEN SQ.ARGUMENT_NAME != '_NULL_' AND SQ.ARGUMENT_NAME != '_null_'
	        THEN SYS.ORA_CASE_TRANS(SQ.ARGUMENT_NAME::VARCHAR2)
	   ELSE
	        NULL
	END::VARCHAR2(128) AS ARGUMENT_NAME,
	SQ.POSITION::NUMBER AS POSITION,
	CASE
		WHEN P.KIND = 'f'
			THEN SQ.POSITION + 1
		ELSE SQ.POSITION
	END::NUMBER AS SEQUENCE,
	0::NUMBER AS DATA_LEVEL,
	CASE
	    /* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'table' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'TABLE'
		  OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'view' OR SQ.TYPE_OBJECT_TYPE::VARCHAR2 = 'VIEW'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'numeric', 'number'])
			THEN 'NUMBER'
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN 'FLOAT'
		WHEN SQ.DATA_TYPE = 'bpchar'
			THEN 'CHAR'
		/* Begin - ReqID:SRS-PLSQL-RECORD */
		WHEN SQ.DATA_TYPE = 'orarecord'
		  THEN 'PL/SQL RECORD'
		/* End - ReqID:SRS-PLSQL-RECORD */
		ELSE ORA_CASE_TRANS(SQ.DATA_TYPE)::VARCHAR2(58)
	END::VARCHAR2(30) AS DATA_TYPE,
	CASE
		WHEN SQ.ARGDEFAULT = '_NULL_'
			THEN 'N'
		ELSE 'Y'
	END::VARCHAR2(1) AS DEFAULTED,
	NULL::LONG AS DEFAULT_VALUE,
	NULL::NUMBER AS DEFAULT_LENGTH,
	CASE
		WHEN SQ.IN_OUT = 'i' OR SQ.IN_OUT IS NULL
			THEN 'IN'
		WHEN SQ.IN_OUT = 'o'
			THEN 'OUT'
		WHEN SQ.IN_OUT = 'b'
			THEN 'IN/OUT'
		ELSE NULL
	END::VARCHAR2(9) AS IN_OUT,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_LENGTH != 0
		    THEN SQ.DATA_LENGTH
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint',
								   'real', 'double precision',
								   'numeric', 'number'])
			THEN 22
		WHEN SQ.DATA_TYPE = ANY(ARRAY['long', 'long_raw'])
			THEN 32760
		ELSE NULL
	END::NUMBER AS DATA_LENGTH,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_PRECISION != 0
		    THEN SQ.DATA_PRECISION
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['smallint', 'integer', 'bigint'])
			THEN 38
		WHEN SQ.DATA_TYPE = 'real'
			THEN 63
		WHEN SQ.DATA_TYPE = 'double precision'
			THEN 126
		WHEN SQ.DATA_TYPE = ANY(ARRAY['timestamp', 'timestamptz',
								   'oratimestamp', 'oratimestamptz',
								   'oratimestampltz'])
			THEN 6
		ELSE NULL
	END::NUMBER AS DATA_PRECISION,
	CASE
		/* Begin - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_SCALE != 0
		    THEN SQ.DATA_SCALE
		/* End - ReqID:SRS-PLSQL-TYPE */
		WHEN SQ.DATA_TYPE = ANY(ARRAY['real', 'double precision'])
			THEN -127
		ELSE NULL
	END::NUMBER AS DATA_SCALE,
	CASE
		WHEN SQ.DATA_TYPE= ANY(ARRAY['numeric', 'number',
								   'smallint', 'integer', 'bigint',
								   'real', 'double precision'])
			THEN 10
		ELSE NULL
	END::NUMBER AS RADIX,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2',
													  'clob'])
			THEN 'CHAR_CS'
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['nchar', 'nvarchar2',
													  'nclob'])
			THEN 'NCHAR_CS'
	END::VARCHAR2(44) AS CHARACTER_SET_NAME,
	NULL::VARCHAR2(128) AS TYPE_OWNER,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_NAME IS NOT NULL AND SQ.TYPE_NAME != '_NULL_' AND SQ.TYPE_NAME != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_NAME)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_NAME,
	/* End - ReqID:SRS-PLSQL-TYPE */
	NULL::VARCHAR2(128) AS TYPE_SUBNAME,
	NULL::VARCHAR2(128) AS TYPE_LINK,
	/* Begin - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE IS NOT NULL AND SQ.TYPE_OBJECT_TYPE != '_NULL_' AND SQ.TYPE_OBJECT_TYPE != '_null_'
		    THEN SYS.ORA_CASE_TRANS(SQ.TYPE_OBJECT_TYPE)::VARCHAR2(128)
		ELSE NULL
	END::VARCHAR2(128) AS TYPE_OBJECT_TYPE,
	CASE
		WHEN SQ.TYPE_OBJECT_TYPE = 'table' OR SQ.TYPE_OBJECT_TYPE = 'TABLE' OR SQ.TYPE_OBJECT_TYPE = 'view' OR SQ.TYPE_OBJECT_TYPE = 'VIEW'
			THEN 'ROWTYPE'
		ELSE NULL
	END::VARCHAR2(30) AS PLS_TYPE,
	/* End - ReqID:SRS-PLSQL-TYPE */
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN NULL
		ELSE 0
	END::NUMBER AS CHAR_LENGTH,
	CASE
		WHEN SQ.DATA_TYPE::VARCHAR2(58) = ANY(ARRAY['char',
													  'character',
													  'varchar2'])
			THEN 'B'
		ELSE '0'
	END::VARCHAR2(1) AS CHAR_USED,
	0::VARCHAR2(256) AS ORIGIN_CON_ID
FROM
	PG_GET_SUBPROCS_IN_PACKAGE() AS P
	LEFT JOIN
	(
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(0, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE KIND = 'f'
		UNION ALL
		SELECT
			OID,
			FNO,
			UNNEST(ARGNAMES) AS ARGUMENT_NAME,
			UNNEST(ARGTYPENAMES) AS DATA_TYPE,
			UNNEST(ARGMODES) AS IN_OUT,
			UNNEST(ARGDEFAULTS) AS ARGDEFAULT,
			GENERATE_SERIES(1, NARGS) AS POSITION,
			/* Begin - ReqID:SRS-PLSQL-TYPE */
			UNNEST(TYPE_NAMES) AS TYPE_NAME,
			UNNEST(TYPE_OBJECT_TYPES) AS TYPE_OBJECT_TYPE,
			UNNEST(DATA_LENGTHS) AS DATA_LENGTH,
			UNNEST(DATA_PRECISIONS) AS DATA_PRECISION,
			UNNEST(DATA_SCALES) AS DATA_SCALE
			/* End - ReqID:SRS-PLSQL-TYPE */
		FROM
			PG_GET_SUBPROCS_IN_PACKAGE() WHERE NARGS > 0 AND KIND = 'p'
	) AS SQ
		ON P.OID = SQ.OID AND P.FNO = SQ.FNO
WHERE
	SQ.POSITION IS NOT NULL
	AND P.NAMESPACE <> 'PG_CATALOG'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'PG_TOAST'::REGNAMESPACE::OID
	AND P.NAMESPACE <> 'INFORMATION_SCHEMA'::REGNAMESPACE::OID
	AND PG_GET_USERBYID(P.OWNER) = CURRENT_USER	/* BUG#M0000074 */
ORDER BY
	OBJECT_ID,OBJECT_NAME
;

GRANT SELECT ON SYS.USER_PACKAGE_ARGUMENTS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_ARGUMENTS AS
	SELECT * FROM SYS.USER_PROC_ARGUMENTS --come from pg_proc
UNION ALL
	SELECT * FROM SYS.USER_PACKAGE_ARGUMENTS --come from pg_package
ORDER BY
	OBJECT_ID,OBJECT_NAME
;
/* End - ReqID:SRS-SQL-PACKAGE */

/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.USER_ARGUMENTS TO PUBLIC;

/* Begin - ReqID:SRS-SQL-SEQ */
/* For sequence VIEWS */
CREATE OR REPLACE VIEW SYS.DBA_SEQUENCES AS
SELECT
	c.relowner::regrole AS sequence_owner,c.relname AS sequence_name,s.seqmin AS min_value,s.seqmax AS max_value,
	s.seqincrement AS increment_by,s.seqcycle AS cycle_flag,null AS order_flag,s.seqcache AS cache_size,
	CASE
		WHEN has_sequence_privilege(c.oid, 'SELECT,USAGE'::text)
			THEN pg_sequence_last_value(c.oid::regclass)
		ELSE NULL::bigint
	END AS last_number,
	decode(bitand(s.flags, 16), 16, 'Y', 'N') AS scale_flag,
	decode(bitand(s.flags, 2048), 2048, 'Y', 'N') AS extend_flag,null AS shared_flag,
	decode(bitand(s.flags, 64), 64, 'Y', 'N') AS session_flag,null AS keep_value
	FROM PG_SEQUENCE s,pg_class c where s.seqrelid = c.oid AND NOT pg_is_other_temp_schema(c.relnamespace); /* BUG#M0000310 */

/* Begin BUG#Z228 */
/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.DBA_SEQUENCES TO PUBLIC;
/* End BUG#Z228 */

CREATE OR REPLACE VIEW SYS.ALL_SEQUENCES AS
SELECT
	c.relowner::regrole AS sequence_owner,c.relname AS sequence_name,s.seqmin AS min_value,s.seqmax AS max_value,
	s.seqincrement AS increment_by,s.seqcycle AS cycle_flag,null AS order_flag,s.seqcache AS cache_size,
	CASE
		WHEN has_sequence_privilege(c.oid, 'SELECT,USAGE'::text)
			THEN pg_sequence_last_value(c.oid::regclass)
		ELSE NULL::bigint
	END AS last_number,
	decode(bitand(s.flags, 16), 16, 'Y', 'N') AS scale_flag,
	decode(bitand(s.flags, 2048), 2048, 'Y', 'N') AS extend_flag,null AS shared_flag,
	decode(bitand(s.flags, 64), 64, 'Y', 'N') AS session_flag,null AS keep_value
	FROM PG_SEQUENCE s,pg_class c where s.seqrelid = c.oid AND NOT pg_is_other_temp_schema(c.relnamespace); /* BUG#M0000310 */

/* Begin BUG#Z228 */
/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.ALL_SEQUENCES TO PUBLIC;
/* End BUG#Z228 */

CREATE OR REPLACE VIEW SYS.USER_SEQUENCES AS
SELECT
	c.relname AS sequence_name,s.seqmin AS min_value,s.seqmax AS max_value,
	s.seqincrement AS increment_by,s.seqcycle AS cycle_flag,null AS order_flag,s.seqcache AS cache_size,
	CASE
		WHEN has_sequence_privilege(c.oid, 'SELECT,USAGE'::text)
			THEN pg_sequence_last_value(c.oid::regclass)
		ELSE NULL::bigint
	END AS last_number,
	decode(bitand(s.flags, 16), 16, 'Y', 'N') AS scale_flag,
	decode(bitand(s.flags, 2048), 2048, 'Y', 'N') AS extend_flag,null AS shared_flag,
	decode(bitand(s.flags, 64), 64, 'Y', 'N') AS session_flag,null AS keep_value
	FROM PG_SEQUENCE s,pg_class c where s.seqrelid = c.oid and pg_get_userbyid(c.relowner) = CURRENT_USER
	AND NOT pg_is_other_temp_schema(c.relnamespace); /* BUG#M0000310 */

/* Begin BUG#Z228 */
/* GRANT SELECT PRIVILEGE TO PUBLIC */
GRANT SELECT ON SYS.USER_SEQUENCES TO PUBLIC;
/* End BUG#Z228 */
/* End - ReqID:SRS-SQL-SEQ */
/* Begin - ReqID:SRS-SQL-FORCEVIEW */
CREATE OR REPLACE VIEW SYS.DBA_VIEWS AS
	SELECT
		SYS.ORA_CASE_TRANS(
			PG_GET_USERBYID(RELOWNER)::VARCHAR2
		)::VARCHAR2(128) AS OWNER,
		SYS.ORA_CASE_TRANS(RELNAME::VARCHAR2)::VARCHAR2(128) AS VIEW_NAME,
		LENGTH(pg_get_viewdef(OID))::NUMBER(38) AS TEXT_LENGTH,
		pg_get_viewdef(OID)::TEXT AS TEXT,
		pg_get_viewdef(OID)::VARCHAR2(4000) AS TEXT_VC,
		NULL::NUMBER(38) AS TYPE_TEXT_LENGTH,
		NULL::VARCHAR2(4000) AS TYPE_TEXT,
		NULL::NUMBER(38) AS OID_TEXT_LENGTH,
		NULL::VARCHAR2(4000) AS OID_TEXT,
		NULL::VARCHAR2(128) AS VIEW_TYPE_OWNER,
		NULL::VARCHAR2(128) AS VIEW_TYPE,
		NULL::VARCHAR2(128) AS SUPERVIEW_NAME,
		NULL::VARCHAR2(1) AS EDITIONING_VIEW,
		NULL::VARCHAR2(1) AS READ_ONLY,
		NULL::VARCHAR2(1) AS CONTAINER_DATA,
		NULL::VARCHAR2(12) AS BEQUEATH,
		0::VARCHAR2(256) AS ORIGIN_CON_ID,
		NULL::VARCHAR2(100) AS DEFAULT_COLLATION,
		NULL::VARCHAR2(3) AS CONTAINERS_DEFAULT,
		NULL::VARCHAR2(3) AS CONTAINER_MAP,
		NULL::VARCHAR2(3) AS EXTENDED_DATA_LINK,
		NULL::VARCHAR2(3) AS EXTENDED_DATA_LINK_MAP,
		NULL::VARCHAR2(3) AS HAS_SENSITIVE_COLUMN,
		NULL::VARCHAR2(3) AS ADMIT_NULL,
		NULL::VARCHAR2(3) AS PDB_LOCAL_ONLY
	FROM
		PG_CLASS
	WHERE
		RELKIND = 'v';
GRANT SELECT ON SYS.DBA_VIEWS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.ALL_VIEWS AS
	SELECT
		SYS.ORA_CASE_TRANS(
			PG_GET_USERBYID(RELOWNER)::VARCHAR2
		)::VARCHAR2(128) AS OWNER,
		SYS.ORA_CASE_TRANS(RELNAME::VARCHAR2)::VARCHAR2(128) AS VIEW_NAME,
		LENGTH(pg_get_viewdef(OID))::NUMBER(38) AS TEXT_LENGTH,
		pg_get_viewdef(OID)::TEXT AS TEXT,
		pg_get_viewdef(OID)::VARCHAR2(4000) AS TEXT_VC,
		NULL::NUMBER(38) AS TYPE_TEXT_LENGTH,
		NULL::VARCHAR2(4000) AS TYPE_TEXT,
		NULL::NUMBER(38) AS OID_TEXT_LENGTH,
		NULL::VARCHAR2(4000) AS OID_TEXT,
		NULL::VARCHAR2(128) AS VIEW_TYPE_OWNER,
		NULL::VARCHAR2(128) AS VIEW_TYPE,
		NULL::VARCHAR2(128) AS SUPERVIEW_NAME,
		NULL::VARCHAR2(1) AS EDITIONING_VIEW,
		NULL::VARCHAR2(1) AS READ_ONLY,
		NULL::VARCHAR2(1) AS CONTAINER_DATA,
		NULL::VARCHAR2(12) AS BEQUEATH,
		0::VARCHAR2(256) AS ORIGIN_CON_ID,
		NULL::VARCHAR2(100) AS DEFAULT_COLLATION,
		NULL::VARCHAR2(3) AS CONTAINERS_DEFAULT,
		NULL::VARCHAR2(3) AS CONTAINER_MAP,
		NULL::VARCHAR2(3) AS EXTENDED_DATA_LINK,
		NULL::VARCHAR2(3) AS EXTENDED_DATA_LINK_MAP,
		NULL::VARCHAR2(3) AS HAS_SENSITIVE_COLUMN,
		NULL::VARCHAR2(3) AS ADMIT_NULL,
		NULL::VARCHAR2(3) AS PDB_LOCAL_ONLY
	FROM
		PG_CLASS
	WHERE
		RELKIND = 'v'
		AND HAS_ANY_COLUMN_PRIVILEGE(OID, 'SELECT');
GRANT SELECT ON SYS.ALL_VIEWS TO PUBLIC;

CREATE OR REPLACE VIEW SYS.USER_VIEWS AS
	SELECT
		SYS.ORA_CASE_TRANS(RELNAME::VARCHAR2)::VARCHAR2(128) AS VIEW_NAME,
		LENGTH(pg_get_viewdef(OID))::NUMBER(38) AS TEXT_LENGTH,
		pg_get_viewdef(OID)::TEXT AS TEXT,
		pg_get_viewdef(OID)::VARCHAR2(4000) AS TEXT_VC,
		NULL::NUMBER(38) AS TYPE_TEXT_LENGTH,
		NULL::VARCHAR2(4000) AS TYPE_TEXT,
		NULL::NUMBER(38) AS OID_TEXT_LENGTH,
		NULL::VARCHAR2(4000) AS OID_TEXT,
		NULL::VARCHAR2(128) AS VIEW_TYPE_OWNER,
		NULL::VARCHAR2(128) AS VIEW_TYPE,
		NULL::VARCHAR2(128) AS SUPERVIEW_NAME,
		NULL::VARCHAR2(1) AS EDITIONING_VIEW,
		NULL::VARCHAR2(1) AS READ_ONLY,
		NULL::VARCHAR2(1) AS CONTAINER_DATA,
		NULL::VARCHAR2(12) AS BEQUEATH,
		0::VARCHAR2(256) AS ORIGIN_CON_ID,
		NULL::VARCHAR2(100) AS DEFAULT_COLLATION,
		NULL::VARCHAR2(3) AS CONTAINERS_DEFAULT,
		NULL::VARCHAR2(3) AS CONTAINER_MAP,
		NULL::VARCHAR2(3) AS EXTENDED_DATA_LINK,
		NULL::VARCHAR2(3) AS EXTENDED_DATA_LINK_MAP,
		NULL::VARCHAR2(3) AS HAS_SENSITIVE_COLUMN,
		NULL::VARCHAR2(3) AS ADMIT_NULL,
		NULL::VARCHAR2(3) AS PDB_LOCAL_ONLY
	FROM
		PG_CLASS
	WHERE
		RELKIND = 'v'
		AND PG_GET_USERBYID(RELOWNER) = CURRENT_USER;
GRANT SELECT ON SYS.USER_VIEWS TO PUBLIC;
/* End - ReqID:SRS-SQL-FORCEVIEW */

/* Begin - ReqID:SRS-PLSQL-CURSOR */
CREATE VIEW sys.v$open_cursor AS
 SELECT saddr::raw(8) AS saddr,
 sid::number AS sid,
 SYS.ORA_CASE_TRANS(user_name)::varchar2(128) AS user_name,
 address::raw(8) AS address,
 hash_value::number AS hash_value,
 sql_id::varchar2(13) AS sql_id,
 sql_text::varchar2(60) AS sql_text,
 last_sql_active_time::DATE AS last_sql_active_time,
 sql_exec_id::number AS sql_exec_id,
 cursor_type::varchar2(64),
 child_address::raw(8) AS child_address,
 con_id::number AS con_id
 FROM ora_open_cursors();
GRANT SELECT ON sys.v$open_cursor TO public;
/* End - ReqID:SRS-PLSQL-CURSOR */

/* Begin - ReqID:SRS-SQL-DBLINK */
CREATE OR REPLACE VIEW sys.ivorysql_dblink as
   SELECT t.lnkname,
    t.lnkowner,
    t.lnkowneroid,
        CASE
            WHEN t.fdwname = 'postgres_fdw'::name THEN 1::oid
            WHEN t.fdwname = 'oracle_fdw'::name THEN 0::oid
            ELSE t.fdwoid
        END AS lnktype,
    t.lnkispublic,
    (SELECT substring(__unnamed_subquery_0.option, length('user='::text) + 1) AS "substring"
           FROM ( SELECT unnest(t.umoptions) AS option) __unnamed_subquery_0
          WHERE __unnamed_subquery_0.option ~~ 'user=%'::text) AS lnkuser,
    '********'::text AS lnkpassword,
    t.lnkconnstr,
    t.lnkacl,
    t.srvoid AS oid,
    t.lnkcreated
   FROM ( SELECT srv.srvname AS lnkname,
            aut.rolname AS lnkowner,
            srv.srvowner AS lnkowneroid,
            true AS lnkispublic,
            srv.olnkusingstring as lnkconnstr,
            srv.srvacl AS lnkacl,
            srv.oid AS srvoid,
            ums.umoptions,
            srv.srvoptions,
            fdw.fdwname,
            fdw.oid AS fdwoid,
            ob.created AS lnkcreated
           FROM pg_foreign_server srv
             JOIN pg_foreign_data_wrapper fdw ON fdw.oid = srv.srvfdw
             LEFT JOIN pg_user_mapping um ON um.umserver = srv.oid AND um.umuser = 0::oid
             LEFT JOIN pg_user_mappings ums ON ums.srvname = srv.srvname AND ums.umuser = 0::oid
             LEFT JOIN pg_authid aut ON aut.oid = srv.srvowner
             LEFT JOIN pg_object ob ON ob.obj_oid = srv.oid
          WHERE srv.olnkispublic = true and srv.olnkconntype != 0
        UNION ALL
         SELECT srv.srvname AS lnkname,
            aut.rolname AS lnkowner,
            srv.srvowner AS lnkowneroid,
            false AS lnkispublic,
            srv.olnkusingstring as lnkconnstr,
            srv.srvacl AS lnkacl,
            srv.oid AS srvoid,
            ums.umoptions,
            srv.srvoptions,
            fdw.fdwname,
            fdw.oid AS fdwoid,
            ob.created AS lnkcreated
           FROM pg_foreign_server srv
             JOIN pg_foreign_data_wrapper fdw ON fdw.oid = srv.srvfdw
             LEFT JOIN pg_user_mapping um ON um.umserver = srv.oid AND um.umuser = srv.srvowner
             LEFT JOIN pg_user_mappings ums ON ums.srvname = srv.srvname AND ums.umuser != 0::oid
             LEFT JOIN pg_authid aut ON aut.oid = srv.srvowner
             LEFT JOIN pg_object ob ON ob.obj_oid = srv.oid
          WHERE srv.olnkispublic = false and srv.olnkconntype != 0) t;
GRANT SELECT ON SYS.ivorysql_dblink TO PUBLIC;
--
-- ALL_DB_LINKS
--
CREATE OR REPLACE VIEW sys.ALL_DB_LINKS as
 SELECT i.lnkowner::VARCHAR2(12) AS owner,
    i.lnkname::VARCHAR2(128) AS db_link,
    i.lnkuser::VARCHAR2(128) AS username,
    NULL::VARCHAR2(128) AS credential_name,
    NULL::VARCHAR2(128) AS credential_owner,
    i.lnkconnstr::VARCHAR2(2000) AS host,
    i.lnkcreated::TIMESTAMP(0)::DATE AS created,
    'no'::VARCHAR2(3) AS hidden,
    'no'::VARCHAR2(3) AS shard_internal,
    'yes'::VARCHAR2(3) AS valid,
    'no'::VARCHAR2(3) AS intra_cdb
   FROM ivorysql_dblink i
  WHERE i.lnkispublic = true OR has_server_privilege(i.oid, 'USAGE'::text);
GRANT SELECT ON SYS.ALL_DB_LINKS TO PUBLIC;
--
-- USER_DB_LINKS
--
CREATE OR REPLACE VIEW sys.USER_DB_LINKS as
 SELECT i.lnkname::VARCHAR2(128) AS db_link,
    i.lnkuser::VARCHAR2(128) AS username,
    i.lnkpassword::VARCHAR2(128) AS password,
    NULL::VARCHAR2(128) AS credential_name,
    NULL::VARCHAR2(128) AS credential_owner,
    i.lnkconnstr::VARCHAR2(2000) AS host,
    i.lnkcreated::TIMESTAMP(0)::DATE AS created,
    'no'::VARCHAR2(3) AS hidden,
    'no'::VARCHAR2(3) AS shard_internal,
    'yes'::VARCHAR2(3) AS valid,
    'no'::VARCHAR2(3) AS intra_cdb
   FROM ivorysql_dblink i
  WHERE pg_get_userbyid(i.lnkowneroid) = current_user AND i.lnkispublic = false;
GRANT SELECT ON SYS.USER_DB_LINKS TO PUBLIC;
--
-- DBA_DB_LINKS
--
CREATE OR REPLACE VIEW sys.DBA_DB_LINKS as
 SELECT
    i.lnkowner::VARCHAR2(12) AS owner,
    i.lnkname::VARCHAR2(128) AS db_link,
    i.lnkuser::VARCHAR2(128) AS username,
    NULL::VARCHAR2(128) AS credential_name,
    NULL::VARCHAR2(128) AS credential_owner,
    i.lnkconnstr::VARCHAR2(2000) AS host,
    i.lnkcreated::TIMESTAMP(0)::DATE AS created,
    'no'::VARCHAR2(3) AS hidden,
    'no'::VARCHAR2(3) AS shard_internal,
    'yes'::VARCHAR2(3) AS valid,
    'no'::VARCHAR2(3) AS intra_cdb
   FROM ivorysql_dblink i;
GRANT SELECT ON SYS.DBA_DB_LINKS TO PUBLIC;
--
-- V$DBLINK
--

CREATE OR REPLACE VIEW sys.V$DBLINK as
  SELECT DISTINCT
    i.lnkname::VARCHAR2(128) as DB_LINK,
    (SELECT oid from pg_roles WHERE rolname = session_user)::INT8::NUMBER as OWNER_ID,
    'yes'::VARCHAR2(3) as LOGGED_ON,
    'no'::VARCHAR2(3) as HETEROGENEOUS,
    'unkn'::VARCHAR2(6) as PROTOCOL,
    1::NUMBER AS OPEN_CURSORS,
    'yes'::VARCHAR2(3) as IN_TRANSACTION,
    'no'::VARCHAR2(3) as UPDATE_SENT,
    1::NUMBER as COMMIT_POINT_STRENGTH,
    1::NUMBER as CON_ID
  FROM sys.ivorysql_dblink i LEFT JOIN pg_foreign_table f ON  f.ftserver = i.oid LEFT JOIN pg_class c ON c.oid = f.ftrelid
   LEFT JOIN pg_namespace n ON c.relnamespace = n.oid
   WHERE  n.nspname LIKE 'pg_temp%' AND
      n.nspname = (SELECT nspname
                   FROM pg_namespace
                   WHERE oid = pg_my_temp_schema());
GRANT SELECT ON SYS.V$DBLINK TO PUBLIC;

--
-- GV$DBLINK
--
CREATE OR REPLACE VIEW sys.GV$DBLINK as
  SELECT DISTINCT
  1::NUMBER as INST_ID,
    i.lnkname::VARCHAR2(128) as DB_LINK,
    (SELECT oid from pg_roles WHERE rolname = session_user)::INT8::NUMBER as OWNER_ID,
    'yes'::VARCHAR2(3) as LOGGED_ON,
    'no'::VARCHAR2(3) as HETEROGENEOUS,
    'unkn'::VARCHAR2(6) as PROTOCOL,
    1::NUMBER AS OPEN_CURSORS,
    'yes'::VARCHAR2(3) as IN_TRANSACTION,
    'no'::VARCHAR2(3) as UPDATE_SENT,
    1::NUMBER as COMMIT_POINT_STRENGTH,
    1::NUMBER as CON_ID
  FROM sys.ivorysql_dblink i LEFT JOIN pg_foreign_table f ON  f.ftserver = i.oid LEFT JOIN pg_class c ON c.oid = f.ftrelid
   LEFT JOIN pg_namespace n ON c.relnamespace = n.oid
   WHERE  n.nspname LIKE 'pg_temp%' AND
      n.nspname = (SELECT nspname
                   FROM pg_namespace
                   WHERE oid = pg_my_temp_schema());
GRANT SELECT ON SYS.GV$DBLINK TO PUBLIC;

--
-- DBA_DB_LINK_SOURCES
--

CREATE OR REPLACE VIEW sys.dba_db_link_sources AS
SELECT
    1::NUMBER AS source_id,
    d.datname::VARCHAR2(256) AS db_name,
    d.oid::INT4::NUMBER AS dbid,
    d.datname::VARCHAR2(256) AS db_unique_name,
    (SELECT ivy_get_host_name())::VARCHAR2(256) AS host_name,
    (SELECT (string_to_array(ivy_get_host_ipv4, ' '))[1])::VARCHAR2(128) AS ip_address,
    'tcp'::VARCHAR2(64) AS protocol,
    (SELECT current_user)::VARCHAR2(128) AS username,
    iu.oid::INT4::NUMBER AS "user#",
    current_timestamp::TIMESTAMP(6) AS first_logon_time,
    current_timestamp::TIMESTAMP(6) AS last_logon_time,
    1::NUMBER AS logon_count
FROM
    pg_roles iu, pg_database d
    WHERE iu.rolname = current_user AND d.datname = current_database;
GRANT SELECT ON SYS.dba_db_link_sources TO PUBLIC;
/* End - ReqID:SRS-SQL-DBLINK */

/* Begin - ReqID:SRS-SQL-TRIGGER */
--
-- ALL_TRIGGERS
--
CREATE OR REPLACE VIEW sys.all_triggers AS
SELECT
    SYS.ORA_CASE_TRANS(usr.usename::varchar2)::varchar2(128) AS owner,
    SYS.ORA_CASE_TRANS(trg.tgname::varchar2)::varchar2(128)  AS trigger_name,
    CASE
        WHEN cls.relkind = 'v' THEN 'INSTEAD OF'
        WHEN trg.tgtype & 2 <> 0 THEN
            CASE
                WHEN trg.tgtype & 1 <> 0 THEN 'BEFORE EACH ROW'
                ELSE 'BEFORE STATEMENT'
            END
        WHEN trg.tgtype & 2 = 0 THEN
            CASE
                WHEN trg.tgtype & 1 <> 0 THEN 'AFTER EACH ROW'
                ELSE 'AFTER STATEMENT'
            END
        ELSE 'UNKNOWN'
    END::varchar2(16)                       AS trigger_type,

    TRIM(BOTH ' ' FROM
        CONCAT_WS(' ',
            CASE WHEN trg.tgtype & 4 <> 0 THEN 'INSERT' END,
            CASE WHEN trg.tgtype & 8 <> 0 THEN 'DELETE' END,
            CASE WHEN trg.tgtype & 16 <> 0 THEN 'UPDATE' END,
            CASE WHEN trg.tgtype & 32 <> 0 THEN 'TRUNCATE' END
        )
    )::varchar2(246)                        AS triggering_event,

    SYS.ORA_CASE_TRANS(usr.usename::varchar2)::varchar2(128)              AS table_owner,
    'TABLE'::varchar2(18)                   AS base_object_type,
    SYS.ORA_CASE_TRANS(cls.relname::varchar2)::varchar2(128)              AS table_name,

    NULL::varchar2(4000)                    AS column_name,

    CASE
        WHEN obj.obj_oid IS NOT NULL AND jsonb_typeof(obj.option->'referencing') = 'array' THEN
            CONCAT (
                'REFERENCING ',
                (
                 SELECT string_agg(elem, ' ')
                 FROM jsonb_array_elements_text(obj.option->'referencing') AS elem
                )
            )
        ELSE NULL
    END::varchar2(422) AS referencing_names,
    pg_get_expr(trg.tgqual, trg.tgrelid)::varchar2(4000) AS when_clause,

	CASE
		WHEN trg.tgenabled = 'O' THEN 'ENABLED'
		WHEN trg.tgenabled = 'A' THEN 'ENABLED'
		WHEN trg.tgenabled = 'D' THEN 'DISABLED'
		ELSE 'UNKNOWN'
	END::varchar2(8) AS status,

    CONCAT('TRIGGER ',
      SYS.ORA_CASE_TRANS(trg.tgname::varchar2),
      ' ON ',
      SYS.ORA_CASE_TRANS(cls.relname::varchar2))::varchar2(4000) AS description,

    SYS.ORA_CASE_TRANS(lang.lanname::varchar2)::varchar2(11)      AS action_type,
    SYS.ORA_CASE_TRANS(p.prosrc::varchar2)::long                  AS trigger_body,

    'NO'::varchar2(7)               AS crosedition,

    CASE WHEN trg.tgtype & 2 <> 0 AND trg.tgtype & 1 = 0 THEN 'YES' ELSE 'NO' END::varchar2(3) AS before_statement,
    CASE WHEN trg.tgtype & 2 <> 0 AND trg.tgtype & 1 <> 0 THEN 'YES' ELSE 'NO' END::varchar2(3) AS before_row,
    CASE WHEN trg.tgtype & 2 = 0 AND trg.tgtype & 1 <> 0 THEN 'YES' ELSE 'NO' END::varchar2(3) AS after_row,
    CASE WHEN trg.tgtype & 2 = 0 AND trg.tgtype & 1 = 0 THEN 'YES' ELSE 'NO' END::varchar2(3) AS after_statement,

    CASE WHEN trg.tgisinternal = false AND cls.relkind = 'v' THEN 'YES' ELSE 'NO' END::varchar2(3) AS instead_of_row,

    'YES'::varchar2(3)                 AS fire_once,
    'NO'::varchar2(3)                  AS apply_server_only

FROM
    pg_trigger trg
JOIN pg_class cls
    ON trg.tgrelid = cls.oid
JOIN pg_user usr
    ON usr.usesysid = cls.relowner
LEFT JOIN pg_proc p
    ON trg.tgfoid = p.oid
LEFT JOIN pg_language lang
    ON p.prolang = lang.oid
LEFT JOIN pg_object obj
    ON obj.obj_oid = trg.oid
WHERE
    NOT trg.tgisinternal;

GRANT SELECT ON sys.all_triggers TO PUBLIC;

--
-- USER_TRIGGERS
--
CREATE OR REPLACE VIEW sys.user_triggers AS
 SELECT at.trigger_name AS trigger_name,
	at.trigger_type AS trigger_type,
	at.triggering_event AS triggering_event,
	at.table_owner AS table_owner,
	at.base_object_type AS base_object_type,
	at.table_name AS table_name,
	at.column_name AS column_name,
	at.referencing_names AS referencing_names,
	at.when_clause AS when_clause,
	at.status AS status,
	at.description AS description,
	at.action_type AS action_type,
	at.trigger_body AS trigger_body,
	at.crosedition AS crosedition,
	at.before_statement AS before_statement,
	at.before_row AS before_row,
	at.after_row AS after_row,
	at.after_statement AS after_statement,
	at.instead_of_row AS instead_of_row,
	at.fire_once AS fire_once,
	at.apply_server_only AS apply_server_only
   FROM sys.all_triggers at
 WHERE at.owner = current_user;

GRANT SELECT ON sys.user_triggers TO PUBLIC;

--
-- DBA_TRIGGERS
--
CREATE OR REPLACE VIEW sys.dba_triggers AS
 SELECT * FROM sys.all_triggers;

GRANT SELECT ON sys.dba_triggers TO PUBLIC;
/* End - ReqID:SRS-SQL-TRIGGER */

/* Begin - ReqID: RQ-SQL-SYSVIEW */
/* *******************************************************************************************
                                          XXX_TABLES
* *******************************************************************************************/
CREATE OR REPLACE VIEW SYS.TABLES_INTERNAL AS
    SELECT
        c.oid AS oid,
        SYS.ORA_CASE_TRANS(PG_GET_USERBYID(c.relowner)::varchar2)::varchar2(128) AS owner,
        SYS.ORA_CASE_TRANS(c.relname::VARCHAR2)::VARCHAR2(128) AS table_name,
        SYS.ORA_CASE_TRANS(
            COALESCE(
                ((SELECT spcname FROM pg_tablespace WHERE oid = c.reltablespace)::VARCHAR2),
                'pg_default')
        )::varchar2(30) AS tablespace_name,
        NULL::varchar2(128) AS cluster_name,
        NULL::varchar2(128) AS iot_name,
        'VALID'::varchar2(8) AS status,
        COALESCE(
            (100 - (SELECT split_part(opt, '=', 2)::integer
             FROM unnest(c.reloptions) AS opt
             WHERE split_part(opt, '=', 1) = 'fillfactor')),
            0
        )::number AS pct_free,
        NULL::number AS pct_used,
        NULL::number AS ini_trans,
        NULL::number AS max_trans,
        NULL::number AS initial_extent,
        NULL::number AS next_extent,
        NULL::number AS min_extents,
        NULL::number AS max_extents,
        NULL::number AS pct_increase,
        NULL::number AS freelists,
        NULL::number AS freelist_groups,
        CASE
            WHEN c.relpersistence = 'p' THEN 'YES'
            ELSE 'NO'
        END::varchar2(3) AS logging,
        'N'::varchar2(1) AS backed_up,
        CASE
            WHEN c.reltuples > -1 THEN c.reltuples
            ELSE NULL
        END::number AS num_rows,
        CASE
            WHEN c.relpages > -1 THEN c.relpages
            ELSE NULL
        END::number AS blocks,
        NULL::number AS empty_blocks,
        NULL::number AS avg_space,
        NULL::number AS chain_cnt,
        (SELECT SUM(stawidth) FROM pg_statistic WHERE starelid = c.oid LIMIT 1)::number AS avg_row_len,
        NULL::number AS avg_space_freelist_blocks,
        NULL::number AS num_freelist_blocks,
        NULL::varchar2(10) AS degree,
        NULL::varchar2(10) AS instances,
        NULL::varchar2(5) AS cache,
        'ENABLED'::varchar2(8) AS table_lock,
        NULL::number AS sample_size,
        TO_CHAR((GREATEST(
                pg_stat_get_last_analyze_time(c.oid),
                pg_stat_get_last_autoanalyze_time(c.oid)
        )), current_setting('nls_date_format'))::date AS last_analyzed,
        CASE
            WHEN c.relkind = 'p' THEN 'YES'
            ELSE 'NO'
        END::varchar2(3) AS partitioned,
        NULL::varchar2(12) AS iot_type,
        CASE
            WHEN c.relpersistence IN ('t', 'g') THEN 'Y'
            ELSE 'N'
        END::varchar2(1) AS temporary,
        'N'::varchar2(1) AS secondary,
        'NO'::varchar2(3) AS nested,
        NULL::varchar2(7) AS buffer_pool,
        NULL::varchar2(7) AS flash_cache,
        NULL::varchar2(7) AS cell_flash_cache,
        'ENABLED'::varchar2(8) AS row_movement,
        'YES'::varchar2(3) AS global_stats,
        'NO'::varchar2(3) AS user_stats,
        CASE
            WHEN c.relpersistence IN ('t', 'g') THEN
                CASE
                    WHEN EXISTS (SELECT 1
                                    FROM unnest(c.reloptions) AS op
                                WHERE
                                    (regexp_match(op, 'on_commit_delete_rows=true') IS NOT NULL)
                                    OR (regexp_match(op, 'on_commit_drop=true') IS NOT NULL))
                        THEN 'SYS$TRANSACTION'
                    ELSE 'SYS$SESSION'
                END
            ELSE NULL
        END::varchar2(15) AS duration,
        CASE
            WHEN current_setting('zero_damaged_pages') = 'off' THEN 'DISABLED'
            ELSE 'ENABLED'
        END::varchar2(8) AS skip_corrupt,
        NULL::varchar2(3) AS monitoring,
        NULL::varchar2(128) AS cluster_owner,
        'DISABLED'::varchar2(8) AS dependencies,
        'DISABLED'::varchar2(8) AS compression,
        NULL::varchar2(30) AS compress_for,
        'NO'::varchar2(3) AS dropped,
        NULL::varchar2(3) AS read_only,
        NULL::varchar2(3) AS segment_created,
        NULL::varchar2(7) AS result_cache,
        'NO'::varchar2(3) AS clustering,
        NULL::varchar2(23) AS activity_tracking,
        NULL::varchar2(25) AS dml_timestamp,
        CASE
           WHEN EXISTS (select 1 from pg_attribute where attrelid = c.oid and attidentity IN ('a', 'd', 'n', 'i', 'o')) THEN 'YES'
           ELSE 'NO'
        END::varchar2(3) AS has_identity,
        'NO'::varchar2(3) AS container_data,
        'DISABLED'::varchar2(8) AS inmemory,
        NULL::varchar2(8) AS inmemory_priority,
        NULL::varchar2(15) AS inmemory_distribute,
        NULL::varchar2(17) AS inmemory_compression,
        NULL::varchar2(13) AS inmemory_duplicate,
        UPPER((SELECT collname FROM pg_collation WHERE oid = (obj.option->>'collation')))::varchar2(100) AS default_collation,
        'N'::varchar2(1) AS duplicated,
        'N'::varchar2(1) AS sharded,
        'N'::varchar2(1) AS externally_sharded,
        'N'::varchar2(1) AS externally_duplicated,
        CASE
            WHEN c.relkind = 'f' THEN 'YES'
            ELSE 'NO'
        END::varchar2(3) AS external,
        'NO'::varchar2(3) AS hybrid,
        NULL::varchar2(24) AS cellmemory,
        'NO'::varchar2(3) AS containers_default,
        'NO'::varchar2(3) AS container_map,
        'NO'::varchar2(3) AS extended_data_link,
        NULL::varchar2(3) AS extended_data_link_map,
        NULL::varchar2(12) AS inmemory_service,
        NULL::varchar2(1000) AS inmemory_service_name,
        'NO'::varchar2(3) AS container_map_object,
        'DISABLED'::varchar2(8) AS memoptimize_read,
        NULL::varchar2(8) AS memoptimize_write,
        'NO'::varchar2(3) AS has_sensitive_column,
        'NO'::varchar2(3) AS admit_null,
        'YES'::varchar2(3) AS data_link_dml_enabled,
        CASE
            WHEN EXISTS (SELECT 1 FROM pg_subscription_rel WHERE srrelid = c.oid)
                OR EXISTS (SELECT 1 FROM pg_publication_rel WHERE prrelid = c.oid) THEN 'ENABLED'
            ELSE 'DISABLED'
        END::varchar2(8) AS logical_replication
    FROM
        pg_class c
    LEFT JOIN
        pg_object obj ON c.oid = obj.obj_oid
    WHERE
        c.relkind IN ('r', 'p', 'f')
        AND c.oid NOT IN (SELECT rcyrelid FROM pg_recyclebin)
        AND c.oid NOT IN (SELECT inhrelid FROM pg_inherits);

