CREATE OR REPLACE VIEW SYS.ALL_TAB_COLUMNS AS
    SELECT 
        owner,
        table_name,
        column_name,
        data_type,
        data_type_mod,
        data_type_owner,
        data_length,
        data_precision,
        data_scale,
